package com.oai.harmonywake; import android.content.*; import org.json.*; import java.util.*; public class TaskStore { static final String P="wake_tasks",K="tasks"; public static List<WakeTask> load(Context c){List<WakeTask> r=new ArrayList<>();try{JSONArray a=new JSONArray(c.getSharedPreferences(P,0).getString(K,"[]"));for(int i=0;i<a.length();i++)r.add(WakeTask.fromJson(a.getJSONObject(i)));}catch(Exception e){}return r;} public static void save(Context c,List<WakeTask> ts){JSONArray a=new JSONArray();try{for(WakeTask t:ts)a.put(t.toJson());}catch(Exception e){}c.getSharedPreferences(P,0).edit().putString(K,a.toString()).apply();} public static WakeTask find(Context c,int id){for(WakeTask t:load(c))if(t.id==id)return t;return null;}}